insert into question_bank (curriculum_id, day_num, difficulty, question, type, options, answer, explanation) values
  ('english_writing', 11, 'beginner', '''나는 아침에 커피를 마신다''를 영어로 옮긴 것은?', 'multiple_choice', '["I drink coffee in the morning.","I drink coffee at the morning.","I drink coffee on the morning.","I drink coffee for the morning."]'::jsonb, 'I drink coffee in the morning.', '하루 중 아침·오후·저녁 앞에는 전치사 in을 씁니다.'),
  ('english_writing', 11, 'beginner', '''책이 탁자 위에 있다''를 영어로 옮긴 것은?', 'multiple_choice', '["The book is on the table.","The book is in the table.","The book is at the table.","The book is over the table."]'::jsonb, 'The book is on the table.', '표면에 접촉해 있을 때는 전치사 on을 씁니다.'),
  ('english_writing', 11, 'beginner', '''우리는 3시에 만날 것이다''를 영어로 옮긴 것은?', 'multiple_choice', '["We will meet at 3 o''clock.","We will meet in 3 o''clock.","We will meet on 3 o''clock.","We will meet by 3 o''clock."]'::jsonb, 'We will meet at 3 o''clock.', '정확한 시각 앞에는 전치사 at을 씁니다.'),
  ('english_writing', 11, 'beginner', '''그녀는 서울에 산다''를 영어로 옮긴 것은?', 'multiple_choice', '["She lives in Seoul.","She lives at Seoul.","She lives on Seoul.","She lives to Seoul."]'::jsonb, 'She lives in Seoul.', '도시·나라처럼 넓은 공간에는 전치사 in을 씁니다.'),
  ('english_writing', 11, 'beginner', '''그는 월요일부터 일한다''를 영어로 쓰시오.', 'short_answer', null, 'He works from Monday.', '''~부터''는 전치사 from으로 나타냅니다.'),
  ('english_writing', 11, 'beginner', '''고양이가 상자 안에 있다''를 영어로 쓰시오.', 'short_answer', null, 'The cat is in the box.', '내부 공간을 나타낼 때는 전치사 in을 씁니다.'),
  ('english_writing', 11, 'beginner', '''나는 저녁까지 기다렸다''를 영어로 쓰시오.', 'short_answer', null, 'I waited until evening.', '동작이 계속되는 끝 시점은 전치사 until로 나타냅니다.'),
  ('english_writing', 11, 'beginner', '''그 다리는 강 위에 있다''를 영어로 쓰시오.', 'short_answer', null, 'The bridge is over the river.', '접촉 없이 위에 있을 때는 전치사 over를 씁니다.'),
  ('english_writing', 11, 'intermediate', '''그 회의는 오후 2시부터 4시까지 계속되었다''를 영어로 옮긴 것은?', 'multiple_choice', '["The meeting lasted from 2 to 4 in the afternoon.","The meeting lasted from 2 to 4 at the afternoon.","The meeting lasted since 2 to 4 in the afternoon.","The meeting lasted from 2 until 4 on the afternoon."]'::jsonb, 'The meeting lasted from 2 to 4 in the afternoon.', '''~부터 ~까지''는 from A to B로 나타내고, 오후는 in the afternoon입니다.'),
  ('english_writing', 11, 'intermediate', '''그녀는 그 파일을 이메일로 보냈다''를 영어로 옮긴 것은?', 'multiple_choice', '["She sent the file by email.","She sent the file with email.","She sent the file on email.","She sent the file in email."]'::jsonb, 'She sent the file by email.', '수단을 나타낼 때는 전치사 by를 씁니다.'),
  ('english_writing', 11, 'intermediate', '''그 상점은 월요일을 제외하고 매일 문을 연다''를 영어로 옮긴 것은?', 'multiple_choice', '["The store is open every day except Monday.","The store is open every day without Monday.","The store is open every day besides Monday.","The store is open every day except of Monday."]'::jsonb, 'The store is open every day except Monday.', '''~을 제외하고''는 전치사 except입니다.'),
  ('english_writing', 11, 'intermediate', '''그 다리는 두 도시 사이에 있다''를 영어로 옮긴 것은?', 'multiple_choice', '["The bridge lies between the two cities.","The bridge lies among the two cities.","The bridge lies between the two cities each.","The bridge lies in between of the two cities."]'::jsonb, 'The bridge lies between the two cities.', '둘 사이는 between, 셋 이상 사이는 among을 씁니다.'),
  ('english_writing', 11, 'intermediate', '''나는 마감일까지 그것을 끝내야 한다''를 영어로 쓰시오.', 'short_answer', null, 'I have to finish it by the deadline.', '완료 시한을 나타낼 때는 전치사 by를 씁니다.'),
  ('english_writing', 11, 'intermediate', '''그 공원은 우리 집 근처에 있다''를 영어로 쓰시오.', 'short_answer', null, 'The park is near my house.', '''~ 근처에''는 전치사 near입니다.'),
  ('english_writing', 11, 'intermediate', '''그녀는 창가 옆에 앉았다''를 영어로 쓰시오.', 'short_answer', null, 'She sat beside the window.', '''~ 옆에''는 전치사 beside입니다.'),
  ('english_writing', 11, 'intermediate', '''그 건물은 은행 맞은편에 있다''를 영어로 쓰시오.', 'short_answer', null, 'The building is across from the bank.', '''~ 맞은편에''는 across from입니다.'),
  ('english_writing', 11, 'advanced', '''그 정책은 새로운 규정에 따라 개정되었다''를 영어로 가장 자연스럽게 옮긴 것은?', 'multiple_choice', '["The policy was revised according to the new regulations.","The policy was revised according with the new regulations.","The policy was revised depending the new regulations.","The policy was revised in accordance the new regulations."]'::jsonb, 'The policy was revised according to the new regulations.', '''~에 따라''는 according to로 나타냅니다.'),
  ('english_writing', 11, 'advanced', '''그 협상은 양측의 합의 없이 진행되었다''를 영어로 옮긴 것은?', 'multiple_choice', '["The negotiation proceeded without an agreement between both sides.","The negotiation proceeded with no an agreement between both sides.","The negotiation proceeded without of an agreement between both sides.","The negotiation proceeded despite an agreement between both sides."]'::jsonb, 'The negotiation proceeded without an agreement between both sides.', '''~ 없이''는 전치사 without입니다.'),
  ('english_writing', 11, 'advanced', '''그 회사는 예산 범위 내에서 그 프로젝트를 완료했다''를 영어로 옮긴 것은?', 'multiple_choice', '["The company completed the project within the budget.","The company completed the project in the budget.","The company completed the project inside of the budget.","The company completed the project under within the budget."]'::jsonb, 'The company completed the project within the budget.', '''~ 범위 내에서''는 전치사 within입니다.'),
  ('english_writing', 11, 'advanced', '''그 도시는 강을 따라 발전해왔다''를 영어로 옮긴 것은?', 'multiple_choice', '["The city has developed along the river.","The city has developed along of the river.","The city has developed following the river.","The city has developed alongside of the river."]'::jsonb, 'The city has developed along the river.', '''~을 따라''는 전치사 along입니다.'),
  ('english_writing', 11, 'advanced', '''그 실험은 엄격한 통제 하에 수행되었다''를 영어로 쓰시오.', 'short_answer', null, 'The experiment was conducted under strict control.', '''~ 하에''는 전치사 under입니다.'),
  ('english_writing', 11, 'advanced', '''그 정책의 효과는 지역에 따라 다르다''를 영어로 쓰시오.', 'short_answer', null, 'The effect of the policy varies according to the region.', '''~에 따라''는 according to로 나타냅니다.'),
  ('english_writing', 11, 'advanced', '''그 협정은 두 나라 간의 오랜 갈등 끝에 체결되었다''를 영어로 쓰시오.', 'short_answer', null, 'The agreement was signed after a long conflict between the two countries.', '''~ 끝에''는 after로, 둘 사이는 between으로 나타냅니다.'),
  ('english_writing', 11, 'advanced', '''그 발견은 수십 년에 걸친 연구 끝에 이루어졌다''를 영어로 쓰시오.', 'short_answer', null, 'The discovery was made after decades of research.', '''~에 걸친''은 decades of research처럼 of로 연결합니다.'),
  ('english_writing', 12, 'beginner', '''나는 피곤했지만 계속 일했다''를 영어로 옮긴 것은?', 'multiple_choice', '["I was tired, but I kept working.","I was tired, but I keep working.","Although I was tired, but I kept working.","I was tired, so I kept working."]'::jsonb, 'I was tired, but I kept working.', '역접의 접속사 but 뒤에는 시제를 일치시킨 문장이 옵니다.'),
  ('english_writing', 12, 'beginner', '''비가 와서 우리는 집에 있었다''를 영어로 옮긴 것은?', 'multiple_choice', '["We stayed home because it rained.","We stayed home because of it rained.","We stayed home so it rained.","We stayed home although it rained."]'::jsonb, 'We stayed home because it rained.', 'because 뒤에는 절(주어+동사)이 옵니다.'),
  ('english_writing', 12, 'beginner', '''그는 똑똑하고 부지런하다''를 영어로 옮긴 것은?', 'multiple_choice', '["He is smart and diligent.","He is smart but diligent.","He is smart, diligent.","He smart and diligent is."]'::jsonb, 'He is smart and diligent.', '두 형용사를 대등하게 연결할 때는 and를 씁니다.'),
  ('english_writing', 12, 'beginner', '''나는 배가 고파서 샌드위치를 먹었다''를 영어로 옮긴 것은?', 'multiple_choice', '["I ate a sandwich because I was hungry.","I ate a sandwich because I am hungry.","I ate a sandwich so I was hungry.","I ate a sandwich although I was hungry."]'::jsonb, 'I ate a sandwich because I was hungry.', '과거의 이유를 나타내므로 because 뒤도 과거시제 was를 씁니다.'),
  ('english_writing', 12, 'beginner', '''서두르지 않으면 늦을 것이다''를 영어로 쓰시오.', 'short_answer', null, 'If you don''t hurry, you will be late.', '조건의 if절에서는 현재시제로 미래를 나타냅니다.'),
  ('english_writing', 12, 'beginner', '''그녀는 노래하면서 요리했다''를 영어로 쓰시오.', 'short_answer', null, 'She cooked while singing.', '''~하면서''는 접속사 while로 나타냅니다.'),
  ('english_writing', 12, 'beginner', '''나는 돈이 없어서 그것을 살 수 없다''를 영어로 쓰시오.', 'short_answer', null, 'I can''t buy it because I have no money.', '이유를 나타내는 because 뒤에는 절이 옵니다.'),
  ('english_writing', 12, 'beginner', '''비록 어렵지만 나는 최선을 다할 것이다''를 영어로 쓰시오.', 'short_answer', null, 'Although it is hard, I will do my best.', '양보의 접속사 although 뒤에는 절이 옵니다.'),
  ('english_writing', 12, 'intermediate', '''그는 늦게 도착했지만 아무도 신경 쓰지 않았다''를 영어로 옮긴 것은?', 'multiple_choice', '["He arrived late, but no one cared.","He arrived late, but no one care.","He arrived late but no one didn''t care.","Although he arrived late, but no one cared."]'::jsonb, 'He arrived late, but no one cared.', 'but 뒤 문장도 과거시제로 일치시킵니다.'),
  ('english_writing', 12, 'intermediate', '''그녀가 열심히 공부했기 때문에 시험에 합격했다''를 영어로 옮긴 것은?', 'multiple_choice', '["She passed the exam because she studied hard.","She passed the exam because of she studied hard.","She passed the exam so she studied hard.","She passed the exam although she studied hard."]'::jsonb, 'She passed the exam because she studied hard.', 'because 뒤에는 절이 오고, because of 뒤에는 명사(구)가 옵니다.'),
  ('english_writing', 12, 'intermediate', '''비록 그 일이 힘들었지만 그는 포기하지 않았다''를 영어로 옮긴 것은?', 'multiple_choice', '["Although the work was hard, he didn''t give up.","Although the work was hard, but he didn''t give up.","Despite the work was hard, he didn''t give up.","The work was hard, although he didn''t give up."]'::jsonb, 'Although the work was hard, he didn''t give up.', 'although와 but을 함께 쓰지 않습니다.'),
  ('english_writing', 12, 'intermediate', '''그가 도착할 때까지 우리는 기다릴 것이다''를 영어로 옮긴 것은?', 'multiple_choice', '["We will wait until he arrives.","We will wait until he will arrive.","We will wait by he arrives.","We will wait until he arrived."]'::jsonb, 'We will wait until he arrives.', '시간의 부사절에서는 미래 대신 현재시제를 씁니다.'),
  ('english_writing', 12, 'intermediate', '''너무 피곤해서 나는 일찍 잠자리에 들었다''를 영어로 쓰시오.', 'short_answer', null, 'I went to bed early because I was so tired.', 'because 뒤에는 절이 옵니다.'),
  ('english_writing', 12, 'intermediate', '''그는 집에 도착하자마자 전화를 걸었다''를 영어로 쓰시오.', 'short_answer', null, 'He called as soon as he got home.', '''~하자마자''는 접속사 as soon as입니다.'),
  ('english_writing', 12, 'intermediate', '''나는 그것에 동의하지 않지만 존중한다''를 영어로 쓰시오.', 'short_answer', null, 'I don''t agree with it, but I respect it.', '역접의 but으로 두 문장을 연결합니다.'),
  ('english_writing', 12, 'intermediate', '''만약 네가 늦으면 우리는 시작할 것이다''를 영어로 쓰시오.', 'short_answer', null, 'If you are late, we will start.', '조건의 if절에서는 현재시제를 씁니다.'),
  ('english_writing', 12, 'advanced', '''그 회사는 손실을 입었음에도 불구하고 계속 성장했다''를 영어로 가장 자연스럽게 옮긴 것은?', 'multiple_choice', '["Although the company suffered losses, it continued to grow.","Although the company suffered losses, but it continued to grow.","Despite the company suffered losses, it continued to grow.","The company suffered losses, although it continued to grow."]'::jsonb, 'Although the company suffered losses, it continued to grow.', 'although 뒤에는 절이 오고, but과 중복해서 쓰지 않습니다.'),
  ('english_writing', 12, 'advanced', '''그 정책이 시행되지 않으면 상황은 악화될 것이다''를 영어로 옮긴 것은?', 'multiple_choice', '["Unless the policy is implemented, the situation will worsen.","Unless the policy is not implemented, the situation will worsen.","If the policy is not implemented, the situation will worse.","Unless the policy will be implemented, the situation will worsen."]'::jsonb, 'Unless the policy is implemented, the situation will worsen.', 'unless는 ''~하지 않으면''이라는 뜻이므로 not과 중복해서 쓰지 않습니다.'),
  ('english_writing', 12, 'advanced', '''그 데이터가 신뢰할 수 없었기 때문에 결론은 보류되었다''를 영어로 옮긴 것은?', 'multiple_choice', '["Since the data was unreliable, the conclusion was withheld.","Since the data was unreliable, but the conclusion was withheld.","Because of the data was unreliable, the conclusion was withheld.","Since the data were unreliable, the conclusion was withheld."]'::jsonb, 'Since the data was unreliable, the conclusion was withheld.', '이유를 나타내는 since 뒤에는 절이 오며, data는 단수로 취급되었습니다.'),
  ('english_writing', 12, 'advanced', '''그 팀은 예산이 부족했음에도 목표를 달성했다''를 영어로 옮긴 것은?', 'multiple_choice', '["Even though the team lacked budget, it achieved the goal.","Even though the team lacked budget, but it achieved the goal.","Despite the team lacked budget, it achieved the goal.","The team lacked budget, even though it achieved the goal."]'::jsonb, 'Even though the team lacked budget, it achieved the goal.', 'even though 뒤에는 절이 오고, but과 중복해서 쓰지 않습니다.'),
  ('english_writing', 12, 'advanced', '''그 제안이 승인되는 즉시 작업이 시작될 것이다''를 영어로 쓰시오.', 'short_answer', null, 'Once the proposal is approved, the work will begin.', '''~하는 즉시''는 접속사 once로 나타냅니다.'),
  ('english_writing', 12, 'advanced', '''그 회의는 예정대로 진행되었으나 결론에는 이르지 못했다''를 영어로 쓰시오.', 'short_answer', null, 'The meeting proceeded as scheduled, but it did not reach a conclusion.', '역접의 but으로 두 절을 연결합니다.'),
  ('english_writing', 12, 'advanced', '''그 결과가 발표되기 전에 자료는 재검토되었다''를 영어로 쓰시오.', 'short_answer', null, 'Before the results were announced, the data was reviewed.', '시간의 접속사 before 뒤에는 절이 옵니다.'),
  ('english_writing', 12, 'advanced', '''그 정책이 효과가 있는 반면 부작용도 있었다''를 영어로 쓰시오.', 'short_answer', null, 'While the policy was effective, it also had side effects.', '대조를 나타낼 때 접속사 while을 씁니다.'),
  ('english_writing', 13, 'beginner', '''이것이 저것보다 크다''를 영어로 옮긴 것은?', 'multiple_choice', '["This is bigger than that.","This is more big than that.","This is bigger that that.","This is the bigger than that."]'::jsonb, 'This is bigger than that.', '1음절 형용사의 비교급은 -er을 붙이고 than을 씁니다.'),
  ('english_writing', 13, 'beginner', '''그녀는 반에서 가장 똑똑하다''를 영어로 옮긴 것은?', 'multiple_choice', '["She is the smartest in the class.","She is the most smart in the class.","She is smartest in the class.","She is the smartest of the class."]'::jsonb, 'She is the smartest in the class.', '1음절 형용사의 최상급은 the+est를 씁니다.'),
  ('english_writing', 13, 'beginner', '''오늘은 어제보다 춥다''를 영어로 옮긴 것은?', 'multiple_choice', '["Today is colder than yesterday.","Today is more cold than yesterday.","Today is colder that yesterday.","Today is the colder than yesterday."]'::jsonb, 'Today is colder than yesterday.', 'cold의 비교급은 colder이고 뒤에 than을 씁니다.'),
  ('english_writing', 13, 'beginner', '''이것은 세상에서 가장 비싼 차다''를 영어로 옮긴 것은?', 'multiple_choice', '["This is the most expensive car in the world.","This is the expensivest car in the world.","This is most expensive car in the world.","This is the more expensive car in the world."]'::jsonb, 'This is the most expensive car in the world.', '3음절 이상의 긴 형용사는 the most를 붙여 최상급을 만듭니다.'),
  ('english_writing', 13, 'beginner', '''그는 나보다 더 빨리 달린다''를 영어로 쓰시오.', 'short_answer', null, 'He runs faster than me.', 'fast의 비교급은 faster이고 뒤에 than을 씁니다.'),
  ('english_writing', 13, 'beginner', '''시간이 돈보다 중요하다''를 영어로 쓰시오.', 'short_answer', null, 'Time is more important than money.', '긴 형용사 important의 비교급은 more important입니다.'),
  ('english_writing', 13, 'beginner', '''이 책이 저 책만큼 재미있다''를 영어로 쓰시오.', 'short_answer', null, 'This book is as interesting as that one.', '동등 비교는 as+원급+as입니다.'),
  ('english_writing', 13, 'beginner', '''그것이 최선의 선택이었다''를 영어로 쓰시오.', 'short_answer', null, 'It was the best choice.', 'good의 최상급은 불규칙 형태인 the best입니다.'),
  ('english_writing', 13, 'intermediate', '''이 제품은 저 제품보다 훨씬 더 비싸다''를 영어로 옮긴 것은?', 'multiple_choice', '["This product is much more expensive than that one.","This product is much expensiver than that one.","This product is more much expensive than that one.","This product is much more expensive as that one."]'::jsonb, 'This product is much more expensive than that one.', '비교급을 강조할 때는 much를 비교급 앞에 씁니다.'),
  ('english_writing', 13, 'intermediate', '''그는 그 팀에서 가장 경험이 많은 직원이다''를 영어로 옮긴 것은?', 'multiple_choice', '["He is the most experienced employee on the team.","He is the most experience employee on the team.","He is most experienced employee on the team.","He is the more experienced employee on the team."]'::jsonb, 'He is the most experienced employee on the team.', 'experienced의 최상급은 the most experienced입니다.'),
  ('english_writing', 13, 'intermediate', '''오늘 회의는 어제 회의만큼 길지 않았다''를 영어로 옮긴 것은?', 'multiple_choice', '["Today''s meeting was not as long as yesterday''s.","Today''s meeting was not so long than yesterday''s.","Today''s meeting was not as longer as yesterday''s.","Today''s meeting was not as long than yesterday''s."]'::jsonb, 'Today''s meeting was not as long as yesterday''s.', '부정의 동등 비교는 not as+원급+as입니다.'),
  ('english_writing', 13, 'intermediate', '''그 도시는 해마다 점점 더 붐빈다''를 영어로 옮긴 것은?', 'multiple_choice', '["The city is getting more and more crowded every year.","The city is getting more crowded and more every year.","The city is getting much more crowded every year.","The city is getting more much crowded every year."]'::jsonb, 'The city is getting more and more crowded every year.', '''점점 더 ~한''은 비교급+and+비교급으로 나타냅니다.'),
